<script setup lang="ts">
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import ConfirmationModal from '@/Components/ConfirmationModal.vue';
import InputError from '@/Components/InputError.vue';
import { Head, router, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';

const props = defineProps<{ templates: any[]; componentKeys: string[]; eventTypes: string[]; defaultSettings: any; headingFonts: string[]; bodyFonts: string[]; alignments: string[]; layoutVariants: string[]; sectionKeys: string[] }>();
const editing = ref<any>(null);
const pendingTemplate = ref<any>(null);
const empty = () => ({ name: '', slug: '', description: '', category: '', component_key: props.componentKeys[0], supported_event_types: [], default_settings: { ...props.defaultSettings, sections: { ...props.defaultSettings.sections } }, is_active: true, display_order: 0 });
const form = useForm(empty());
const edit = (template: any) => { editing.value = template; form.defaults({ ...empty(), ...template, supported_event_types: template.supported_event_types || [], default_settings: { ...props.defaultSettings, ...(template.default_settings || {}), sections: { ...props.defaultSettings.sections, ...(template.default_settings?.sections || {}) } } }); form.reset(); };
const cancel = () => { editing.value = null; form.defaults(empty()); form.reset(); };
const submit = () => editing.value ? form.put(route('admin.templates.update', editing.value.id), { onSuccess: cancel }) : form.post(route('admin.templates.store'), { onSuccess: cancel });
const setActive = () => router.patch(route('admin.templates.active', pendingTemplate.value.id), { is_active: !pendingTemplate.value.is_active }, { onFinish: () => { pendingTemplate.value = null; } });
const error = (key: string) => (form.errors as Record<string, string | undefined>)[key];
</script>

<template>
    <Head title="Templates" />
    <AuthenticatedLayout><template #header><h2 class="text-xl font-semibold">Invitation Templates</h2></template><div class="mx-auto max-w-6xl space-y-6 p-6"><form class="grid gap-4 rounded bg-white p-6 shadow sm:grid-cols-2" @submit.prevent="submit"><h3 class="sm:col-span-2 text-lg font-semibold">{{ editing ? 'Edit template metadata' : 'Add template metadata' }}</h3><div><label class="block text-sm">Name</label><input v-model="form.name" required class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.name" class="mt-1" /></div><div><label class="block text-sm">Slug / key</label><input v-model="form.slug" required class="mt-1 w-full rounded border-gray-300"><InputError :message="form.errors.slug" class="mt-1" /></div><div><label class="block text-sm">Category</label><input v-model="form.category" class="mt-1 w-full rounded border-gray-300"></div><div><label class="block text-sm">Trusted renderer</label><select v-model="form.component_key" class="mt-1 w-full rounded border-gray-300"><option v-for="key in componentKeys" :key="key" :value="key">{{ key }}</option></select></div><div class="sm:col-span-2"><label class="block text-sm">Description</label><textarea v-model="form.description" class="mt-1 w-full rounded border-gray-300" /></div><fieldset class="sm:col-span-2"><legend class="text-sm">Supported Event types</legend><label v-for="type in eventTypes" :key="type" class="mr-4 inline-flex items-center gap-1 text-sm"><input v-model="form.supported_event_types" type="checkbox" :value="type"> {{ type.replaceAll('_', ' ') }}</label></fieldset><div><label class="block text-sm">Primary default color</label><input v-model="form.default_settings.primary_color" class="mt-1 w-full rounded border-gray-300"><InputError :message="error('default_settings.primary_color')" class="mt-1" /></div><div><label class="block text-sm">Secondary default color</label><input v-model="form.default_settings.secondary_color" class="mt-1 w-full rounded border-gray-300"></div><div><label class="block text-sm">Heading font</label><select v-model="form.default_settings.heading_font" class="mt-1 w-full rounded border-gray-300"><option v-for="font in headingFonts" :key="font" :value="font">{{ font.replaceAll('_', ' ') }}</option></select></div><div><label class="block text-sm">Body font</label><select v-model="form.default_settings.body_font" class="mt-1 w-full rounded border-gray-300"><option v-for="font in bodyFonts" :key="font" :value="font">{{ font }}</option></select></div><div><label class="block text-sm">Text alignment</label><select v-model="form.default_settings.text_alignment" class="mt-1 w-full rounded border-gray-300"><option v-for="alignment in alignments" :key="alignment" :value="alignment">{{ alignment }}</option></select></div><div><label class="block text-sm">Layout variant</label><select v-model="form.default_settings.layout_variant" class="mt-1 w-full rounded border-gray-300"><option v-for="variant in layoutVariants" :key="variant" :value="variant">{{ variant }}</option></select></div><fieldset class="sm:col-span-2"><legend class="text-sm">Default visible sections</legend><label v-for="key in sectionKeys" :key="key" class="mr-4 inline-flex items-center gap-1 text-sm"><input v-model="form.default_settings.sections[key]" type="checkbox"> {{ key.replaceAll('_', ' ') }}</label></fieldset><div><label class="block text-sm">Display order</label><input v-model="form.display_order" type="number" min="0" class="mt-1 w-full rounded border-gray-300"></div><label class="flex items-center gap-2 self-end"><input v-model="form.is_active" type="checkbox"> Active</label><div class="sm:col-span-2 flex gap-3"><button class="rounded bg-indigo-600 px-4 py-2 text-white">{{ editing ? 'Save template' : 'Create template' }}</button><button v-if="editing" type="button" class="text-gray-600" @click="cancel">Cancel</button></div></form><div class="overflow-x-auto rounded bg-white shadow"><table class="min-w-full text-left text-sm"><thead class="bg-gray-50"><tr><th class="p-3">Template</th><th class="p-3">Renderer</th><th class="p-3">Order</th><th class="p-3">Events</th><th class="p-3">Status</th><th class="p-3"></th></tr></thead><tbody><tr v-for="template in templates" :key="template.id" class="border-t"><td class="p-3"><strong>{{ template.name }}</strong><p class="text-gray-500">{{ template.slug }}</p></td><td class="p-3">{{ template.component_key }}</td><td class="p-3">{{ template.display_order }}</td><td class="p-3">{{ template.events_count }}</td><td class="p-3">{{ template.is_active ? 'Active' : 'Inactive' }}</td><td class="p-3"><button class="text-indigo-600" @click="edit(template)">Edit</button><button class="ml-3 text-indigo-600" @click="pendingTemplate = template">{{ template.is_active ? 'Deactivate' : 'Reactivate' }}</button></td></tr><tr v-if="!templates.length"><td colspan="6" class="p-5 text-center text-gray-600">No templates have been added.</td></tr></tbody></table></div></div><ConfirmationModal :show="!!pendingTemplate" :title="pendingTemplate?.is_active ? 'Deactivate template?' : 'Reactivate template?'" :message="pendingTemplate?.is_active ? 'Existing Event assignments will remain, but this template cannot be newly selected.' : 'This template will become selectable again.'" :confirm-label="pendingTemplate?.is_active ? 'Deactivate' : 'Reactivate'" @close="pendingTemplate = null" @confirm="setActive" /></AuthenticatedLayout>
</template>
